func square(ctx context.Context, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out) // sender owns & closes its output
		for n := range in { // ends when in is closed & drained
			select {
			case out <- n * n: // normal send
			case <-ctx.Done(): // consumer cancelled -> exit, no leak
				return
			}
		}
	}()
	return out
}
